function closeTools(){
 $('#topActions').classList.remove('open');
 $('#toolsToggle').setAttribute('aria-expanded','false');
}
window.addEventListener('resize',()=>{if(!narrowView()){closeNavigation(false);closeTools()}});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'){
  if(document.getElementById('fieldHelpPopup'))closeFieldHelp(true);
  else if($('#modal').innerHTML.trim())closeModal();
  else if($('#sidebar').classList.contains('open'))closeNavigation(true);
  else if($('#topActions').classList.contains('open')){closeTools();$('#toolsToggle').focus()}
 }
});
document.addEventListener('click',e=>{
 const trigger=e.target.closest('[data-field-help]');
 if(trigger){e.preventDefault();e.stopImmediatePropagation();showFieldHelp(trigger);return;}
 if(document.getElementById('fieldHelpPopup') && !e.target.closest('#fieldHelpPopup'))closeFieldHelp(false);
},true);
document.addEventListener('click',e=>{let tabButton=e.target.closest('[data-tab]'),edit=e.target.closest('[data-edit]'),scenario=e.target.closest('[data-scenario]'),actionEl=e.target.closest('[data-action]');if(tabButton){tab=tabButton.dataset.tab;filter='';main();window.scrollTo(0,0)}else if(edit)openEditor(Number(edit.dataset.edit));else if(scenario){selectedScenario=Number(scenario.dataset.scenario);academyResponse='';showFeedback=false;main()}else if(actionEl){let a=actionEl.dataset.action;closeTools();if(a==='savemeta')doMeta();else action(a)}else if(e.target.closest('#hamburger'))toggleNavigation();else if(e.target.closest('#closeNav')||e.target.id==='sidebarBackdrop')closeNavigation(true);else if(e.target.closest('#toolsToggle'))toggleTools();else if(e.target.id==='modalBg')closeModal()});
document.addEventListener('input',e=>{if(e.target.closest('#recordFields')&&tab==='capacity'){const fields=$('#recordFields');let r=Object.fromEntries([...fields.querySelectorAll('[name]')].map(el=>[el.name,el.value]));const target=fields.querySelector('[name=available]');if(target)target.value=Number.isFinite(availableDays(r))?availableDays(r):'';}if(e.target.id==='recordSearch'){filter=e.target.value;let p=e.target.selectionStart;let el=e.target;const body=el.closest('.panel').querySelector('tbody');let keys=window.FIELDS[tab];let shown=rows(tab).map((x,i)=>({...x,__row:i})).filter(x=>Object.values(x).some(v=>String(v).toLowerCase().includes(filter.toLowerCase())));body.innerHTML=renderRecordRows(shown,keys)}else if(e.target.id==='referenceSearch'){referenceQuery=e.target.value;let pre=$('.reading');let match=window.REFERENCE.split('\n').filter(x=>x.toLowerCase().includes(referenceQuery.toLowerCase()));pre.textContent=referenceQuery?match.join('\n')||'No matching lines.':window.REFERENCE}else if(e.target.id==='answer')academyResponse=e.target.value});
document.addEventListener('change',async e=>{if(e.target.id==='workspacePicker'){switchWorkspace(e.target.value);return}if(e.target.id==='mode'){mode=e.target.value;main();closeTools()}if(e.target.id==='importFile'){let file=e.target.files?.[0], destination=workspaceId;if(!file)return;try{let data=JSON.parse(await file.text());if(destination!==workspaceId)throw Error('Workspace changed. Select the file again.');if(!data?.modules||!data?.metadata||Object.keys(window.STARTER.modules).some(k=>!Array.isArray(data.modules[k]))||!Array.isArray(data.modules.financials)||!Array.isArray(data.modules.roadmap))throw Error('Invalid workspace structure');if(confirm('Import workspace and replace local edits?')){state=data;save();main();toast('Workspace imported. Check Data Integrity Audit for warnings.')}}catch(err){toast('Import failed: '+err.message)}e.target.value=''}});
